import sys, zipfile, re
import xml.etree.ElementTree as ET

path = sys.argv[1] if len(sys.argv) > 1 else 'sales_data.xlsx'

for mod in ('openpyxl', 'xlsxwriter', 'xlrd', 'pyxlsb'):
    try:
        __import__(mod)
        print(f"module {mod}: AVAILABLE")
    except Exception as e:
        print(f"module {mod}: missing ({type(e).__name__})")

NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'rel': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'pr': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

z = zipfile.ZipFile(path)
print("\nArchive entries:")
for n in z.namelist():
    print("  ", n)

wb_xml = ET.fromstring(z.read('xl/workbook.xml'))
rels_xml = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rid_to_target = {}
for rel in rels_xml:
    rid_to_target[rel.attrib['Id']] = rel.attrib['Target']

sheet_defs = []
for sh in wb_xml.find('main:sheets', NS):
    rid = sh.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']
    sheet_defs.append((sh.attrib['name'], rid_to_target[rid].lstrip('/')))
print("\nSheets:", sheet_defs)

shared = []
try:
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sst.findall('main:si', NS):
        txt = ''.join(t.text or '' for t in si.iter('{%s}t' % NS['main']))
        shared.append(txt)
except KeyError:
    pass
print(f"\nShared strings ({len(shared)}):", shared[:60])

def col_letter(ref):
    return re.match(r'[A-Z]+', ref).group(0)

for name, target in sheet_defs:
    xml_path = 'xl/' + target if not target.startswith('xl/') else target
    print(f"\n=== Sheet '{name}' ({xml_path}) ===")
    root = ET.fromstring(z.read(xml_path))
    sd = root.find('main:sheetData', NS)
    if sd is None:
        print("  no sheetData")
        continue
    for i, row in enumerate(sd.findall('main:row', NS)):
        cells = []
        for c in row.findall('main:c', NS):
            ref = c.attrib.get('r', '?')
            t = c.attrib.get('t')
            v = c.find('main:v', NS)
            isel = c.find('main:is', NS)
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr' and isel is not None:
                val = ''.join(tt.text or '' for tt in isel.iter('{%s}t' % NS['main']))
            elif v is not None:
                val = v.text
            else:
                val = ''
            cells.append(f"{ref}={val!r}(t={t})")
        print(f"  row {i+1}:", ' | '.join(cells))
        if i >= 8:
            print("  ... (truncated)")
            break

