import zipfile, re, sys, os
import xml.etree.ElementTree as ET

NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
RNS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
for pfx, uri in [('', NS), ('r', RNS), ('mc', 'http://schemas.openxmlformats.org/markup-compatibility/2006'),
                 ('x14ac', 'http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac'),
                 ('x15', 'http://schemas.microsoft.com/office/spreadsheetml/2010/11/main')]:
    ET.register_namespace(pfx, uri)

path = sys.argv[1] if len(sys.argv) > 1 else 'sales_data.xlsx'

def col_letter(idx):
    letters = ''
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        letters = chr(65 + rem) + letters
    return letters

def col_index(ref):
    m = re.match(r'([A-Z]+)(\d+)$', ref or '')
    if not m:
        return None
    idx = 0
    for ch in m.group(1):
        idx = idx * 26 + (ord(ch) - 64)
    return idx

def resolve(target):
    if target.startswith('/'):
        return target.lstrip('/')
    if target.startswith('xl/'):
        return target
    return 'xl/' + target

zin = zipfile.ZipFile(path)
names = zin.namelist()
parts = {n: zin.read(n) for n in names}
zin.close()

wb_root = ET.fromstring(parts['xl/workbook.xml'])
sheets = [(sh.get('name'), sh.get('{%s}id' % RNS)) for sh in wb_root.iter('{%s}sheet' % NS)]
rels_root = ET.fromstring(parts['xl/_rels/workbook.xml.rels'])
rid_to_target = {rel.get('Id'): rel.get('Target') for rel in rels_root}

shared = []
ss_name = next((n for n in names if 'sharedStrings' in n), None)
if ss_name:
    ss_root = ET.fromstring(parts[ss_name])
    for si in ss_root.iter('{%s}si' % NS):
        shared.append(''.join(t.text or '' for t in si.iter('{%s}t' % NS)))

def cell_value(c):
    t = c.get('t')
    v = c.find('{%s}v' % NS)
    if t == 's' and v is not None:
        try:
            return shared[int(v.text)]
        except Exception:
            return None
    if t == 'inlineStr':
        is_ = c.find('{%s}inlineStr' % NS)
        if is_ is not None:
            return ''.join(x.text or '' for x in is_.iter('{%s}t' % NS))
        return None
    if t == 'str':
        return v.text if v is not None else None
    if v is not None:
        return v.text
    return None

style_idx = None
try:
    st_root = ET.fromstring(parts['xl/styles.xml'])
    cellxfs = st_root.find('{%s}cellXfs' % NS)
    if cellxfs is not None:
        xfs = cellxfs.findall('{%s}xf' % NS)
        style_idx = len(xfs)
        try:
            numfmts = st_root.find('{%s}numFmts' % NS)
            taken = set()
            if numfmts is not None:
                for nf in numfmts.findall('{%s}numFmt' % NS):
                    try:
                        taken.add(int(nf.get('numFmtId')))
                    except Exception:
                        pass
            fmt_id = 164
            while fmt_id in taken:
                fmt_id += 1
            nf_el = ET.Element('{%s}numFmt' % NS, {'numFmtId': str(fmt_id), 'formatCode': '0.0%'})
            if numfmts is None:
                numfmts = ET.Element('{%s}numFmts' % NS, {'count': '1'})
                numfmts.append(nf_el)
                st_root.insert(0, numfmts)
            else:
                numfmts.append(nf_el)
                numfmts.set('count', str(len(numfmts.findall('{%s}numFmt' % NS))))
        except Exception:
            fmt_id = 10
        xf_el = ET.Element('{%s}xf' % NS, {'numFmtId': str(fmt_id), 'fontId': '0', 'fillId': '0',
                                          'borderId': '0', 'xfId': '0', 'applyNumberFormat': '1'})
        cellxfs.append(xf_el)
        cellxfs.set('count', str(len(xfs) + 1))
        parts['xl/styles.xml'] = ET.tostring(st_root, xml_declaration=True, encoding='UTF-8')
except Exception as e:
    print('style skipped:', e)
    style_idx = None

modified = False
for name, rid in sheets:
    target = resolve(rid_to_target.get(rid, ''))
    if target not in parts:
        print(f"[{name}] sheet xml not found ({target}), skipped")
        continue
    sroot = ET.fromstring(parts[target])
    rows = {}
    max_row = 0
    max_col = 0
    for row in sroot.iter('{%s}row' % NS):
        rattr = row.get('r')
        r = int(rattr) if rattr else len(rows) + 1
        rows[r] = row
        max_row = max(max_row, r)
        for c in row.iter('{%s}c' % NS):
            ci = col_index(c.get('r'))
            if ci:
                max_col = max(max_col, ci)

    header_row = None
    for r in sorted(rows):
        if any(isinstance(cell_value(c), str) and cell_value(c).strip() for c in rows[r].iter('{%s}c' % NS)):
            header_row = r
            break
    if header_row is None:
        print(f"[{name}] no header row, skipped")
        continue

    headers = {}
    for c in rows[header_row].iter('{%s}c' % NS):
        ci = col_index(c.get('r'))
        if ci:
            headers[ci] = cell_value(c)

    def find_col(kws):
        for ci in sorted(headers):
            v = headers[ci]
            if isinstance(v, str) and any(k in v.strip().lower() for k in kws):
                return ci, v
        return None, None

    profit_col, profit_name = find_col(['profit'])
    rev_col, rev_name = find_col(['revenue', 'sales'])
    cost_col, cost_name = find_col(['cost'])
    if rev_col is None or (profit_col is None and cost_col is None):
        print(f"[{name}] no matching columns (rev={rev_col}, profit={profit_col}, cost={cost_col}), skipped")
        continue

    new_col = max_col + 1
    hdr_cell = ET.Element('{%s}c' % NS, {'r': '%s%d' % (col_letter(new_col), header_row), 't': 'inlineStr'})
    is_el = ET.SubElement(hdr_cell, '{%s}is' % NS)
    t_el = ET.SubElement(is_el, '{%s}t' % NS)
    t_el.text = 'Profit Margin (%)'
    rows[header_row].append(hdr_cell)

    added = 0
    for r in range(header_row + 1, max_row + 1):
        if r not in rows:
            continue
        has_val = any((cell_value(c) not in (None, '')) for c in rows[r].iter('{%s}c' % NS))
        if not has_val:
            continue
        if profit_col is not None:
            expr = '%s%d/%s%d' % (col_letter(profit_col), r, col_letter(rev_col), r)
        else:
            expr = '(%s%d-%s%d)/%s%d' % (col_letter(rev_col), r, col_letter(cost_col), r, col_letter(rev_col), r)
        formula = 'IF(%s%d=0,"",%s)' % (col_letter(rev_col), r, expr)
        attrs = {'r': '%s%d' % (col_letter(new_col), r)}
        if style_idx is not None:
            attrs['s'] = str(style_idx)
        new_c = ET.Element('{%s}c' % NS, attrs)
        f_el = ET.SubElement(new_c, '{%s}f' % NS)
        f_el.text = formula
        rows[r].append(new_c)
        added += 1

    parts[target] = ET.tostring(sroot, xml_declaration=True, encoding='UTF-8')
    modified = True
    print(f"[{name}] added column {col_letter(new_col)} 'Profit Margin (%)' ({added} data rows; "
          f"margin = {profit_name or (rev_name + ' - ' + cost_name)} / {rev_name})")

if modified:
    calcPr = wb_root.find('{%s}calcPr' % NS)
    if calcPr is None:
        calcPr = ET.Element('{%s}calcPr' % NS, {'calcId': '0', 'fullCalcOnLoad': '1'})
        wb_root.append(calcPr)
    else:
        calcPr.set('fullCalcOnLoad', '1')
    parts['xl/workbook.xml'] = ET.tostring(wb_root, xml_declaration=True, encoding='UTF-8')

    tmp = path + '.tmp'
    with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as zout:
        for n in names:
            zout.writestr(n, parts[n])
    os.replace(tmp, path)
    print('saved', path)
else:
    print('nothing modified')

